128	  public static void serverTick(
129	      Level level, BlockPos pos, BlockState state, PlanterBlockEntity planter) {
130	    if (planter.ticksSinceCore <= STALE_TICKS && ++planter.ticksSinceCore > STALE_TICKS) {
131	      planter.stopFromCore();
132	    }
133	    boolean wantActive =
134	        planter.status == PlanterStatus.GROWING || planter.status == PlanterStatus.SHORT_ON_SOIL;
135	    planter.inactiveTicks = wantActive ? 0 : Math.min(planter.inactiveTicks + 1, ACTIVE_OFF_DELAY);
136	    boolean active = state.getValue(PlanterBlock.ACTIVE);
137	    if (wantActive != active && (wantActive || planter.inactiveTicks >= ACTIVE_OFF_DELAY)) {
138	      level.setBlock(pos, state.setValue(PlanterBlock.ACTIVE, wantActive), Block.UPDATE_ALL);
139	    }
140	  }
141	
142	  public void tickFromCore(TickContext ctx) {
143	    ticksSinceCore = 0;
144	    lastDraw = 0;
145	    boolean holding = false;
146	    if (!heldOutputs.isEmpty()) {
147	      flushHeldOutputs(ctx.outputs());
148	      setChanged();
149	      holding = !heldOutputs.isEmpty();
150	    }
151	
152	    int soilCount = soilAndUpgrades.getAmountAsInt(SOIL);
153	    ItemStack soil = soilAndUpgrades.getResource(SOIL).toStack(soilCount);
154	    Optional<AteBridge.PlantRecipe> recipe =
155	        seeds.size() == 0 || soil.isEmpty()
156	            ? Optional.empty()
157	            : recipes.get(ctx.level(), seeds.seed(0));
158	    if (recipe.isEmpty() || !recipe.get().soilMatches().test(soil)) {
159	      if (holding) {
160	        setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
161	        return;
162	      }
163	      seeds.resetAll();
164	      growing = 0;
165	      upgraded = 0;
166	      setStatus(PlanterStatus.IDLE);
167	      setChanged();
168	      return;
169	    }
170	
171	    int nowGrowing = Coverage.growing(seeds.size(), soilCount);
172	    UpgradeKind kind1 = upgradeKind(UPGRADE_1);
173	    UpgradeKind kind2 = upgradeKind(UPGRADE_2);
174	    int count1 = upgradeCount(UPGRADE_1, kind1);
175	    int count2 = upgradeCount(UPGRADE_2, kind2);
176	    List<Group> groups =
177	        Grouping.of(seeds, Coverage.assign(nowGrowing, kind1, count1, kind2, count2));
178	
179	    // Each group decides once per tick, before any pause, so a paused group still holds its claim
180	    // and one decision sets both its growth time and its harvest.
181	    Map<Group, FertilizerData> fertilized = new HashMap<>();
182	    for (Group group : groups) {
183	      FertilizerData claimed = ctx.fertilizer().claim(group.size());
184	      if (claimed != null) {
185	        fertilized.put(group, claimed);
186	      }
187	    }
188	    if (holding) {
189	      setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
190	      return;
191	    }
192	
193	    growing = nowGrowing;
194	    seeds.resetFrom(growing);
195	    upgraded = Coverage.upgraded(growing, count1, count2);
196	
197	    AteNumbers numbers = ctx.numbers();
198	    float soilModifier = AteBridge.soilModifier(soil);
199	    PlanterStatus paused = null;
200	    PlanterTicker.AdvanceResult result =
201	        PlanterTicker.advance(
202	            seeds,
203	            groups,
204	            group -> processingTime(ctx, group, soilModifier, fertilized.get(group)),
205	            upgrades -> GrowthMath.powerPerSeedTick(numbers, upgrades),
206	            ctx.power().stored());
207	    if (result.pausedForPower()) {
208	      paused = PlanterStatus.PAUSED_FOR_POWER;
209	    } else {
210	      // This take can't fail, because advance was given ctx.power().stored() and only charges what
211	      // that covers.
212	      ctx.power().tryTake(result.energyUsed());
213	      lastDraw = result.energyUsed();
214	    }
215	
216	    for (Group group : groups) {
217	      if (!seeds.ready(group.first())) {
218	        continue;
219	      }
220	      FertilizerData fertilizer = fertilized.get(group);
221	      float fertilizerYield = fertilizer != null ? fertilizer.yieldMultiplier() : 1.0f;
222	      float upgradeYield = group.upgrades().yieldModifier(numbers);
223	      float modifier = fertilizerYield * upgradeYield * (float) numbers.clocheYield();
224	      if (!ctx.outputs().hasRoomFor(listedDrops(recipe.get().drops(), modifier, group.size()))) {
225	        paused = PlanterStatus.PAUSED_EXPORT_FULL;
226	        break;
227	      }
228	      for (int seed : group.seeds()) {
229	        harvest(ctx, seed, fertilizer != null, fertilizerYield, upgradeYield, modifier);
230	      }
231	      // Outputs that did not fit are held until they leave, so later groups wait instead of adding
232	      // more to the pile.
233	      if (!heldOutputs.isEmpty()) {
234	        break;
235	      }
236	    }
237	
238	    if (!heldOutputs.isEmpty()) {
239	      setStatus(PlanterStatus.PAUSED_EXPORT_FULL);
240	    } else if (paused != null) {
241	      setStatus(paused);
242	    } else if (growing < seeds.size()) {
243	      setStatus(PlanterStatus.SHORT_ON_SOIL);
244	    } else {
245	      setStatus(PlanterStatus.GROWING);
246	    }
247	    setChanged();
248	  }
249	
250	  public void stopFromCore() {
251	    lastDraw = 0;
252	    growing = 0;
253	    upgraded = 0;
254	    setStatus(PlanterStatus.IDLE);
255	  }
256	
257	  private UpgradeKind upgradeKind(int slot) {
258	    return AteBridge.upgradeKind(soilAndUpgrades.getResource(slot).toStack());
259	  }
260	
261	  private int upgradeCount(int slot, UpgradeKind kind) {
262	    return kind == UpgradeKind.NONE ? 0 : soilAndUpgrades.getAmountAsInt(slot);
263	  }
264	
265	  private int processingTime(
266	      TickContext ctx, Group group, float soilModifier, @Nullable FertilizerData fertilizer) {
267	    float fertilizerSpeed = fertilizer != null ? fertilizer.speedMultiplier() : 1.0f;
268	    int time =
269	        GrowthMath.growthTime(ctx.numbers(), soilModifier, group.upgrades(), fertilizerSpeed);
270	    return NeoForge.EVENT_BUS
271	        .post(new PlanterProcessingTimeEvent(this, seeds.seed(group.first()).copy(), time))
272	        .getProcessingTime();
273	  }
274	
275	  // Each drop entry gets one more item per seed than ATE's rounding gives, because the cloche adds
276	  // at most one extra item per drop and harvest.
277	  private static List<ItemStack> listedDrops(List<DropEntry> drops, float modifier, int seedCount) {
278	    List<ItemStack> listed = new ArrayList<>(drops.size());
279	    for (DropEntry entry : drops) {
280	      listed.add(
281	          new ItemStack(
282	              entry.item(), (ClocheYield.ateCount(entry.max(), modifier) + 1) * seedCount));
283	    }
284	    return listed;
285	  }
286	
287	  private void harvest(
288	      TickContext ctx,
289	      int index,
290	      boolean fertilized,
291	      float fertilizerYield,
292	      float upgradeYield,
293	      float modifier) {
294	    ItemStack stored = seeds.seed(index);
295	    ItemStack seed =
296	        NeoForge.EVENT_BUS.post(new PlanterPreHarvestEvent(this, stored.copy())).getSeed();
297	    if (!seed.isEmpty() && !ItemStack.matches(seed, stored)) {
298	      seeds.replaceSeed(index, seed.copyWithCount(1));
299	    }
300	
301	    List<ItemStack> rolled =
302	        recipes
303	            .get(ctx.level(), seed)
304	            .map(recipe -> AteBridge.rollDrops(recipe.drops(), ctx.random()))
305	            .orElse(List.of());
306	    List<ItemStack> drops = new ArrayList<>(rolled.size());
307	    List<ItemStack> extras = new ArrayList<>();
308	    for (ItemStack raw : rolled) {
309	      drops.add(raw.copyWithCount(ClocheYield.ateCount(raw.getCount(), modifier)));
310	      long kept =
311	          ClocheYield.keptMicros(
312	              raw.getCount(), fertilizerYield, upgradeYield, ctx.numbers().clocheYield());
313	      int extra =
314	          clocheRemainders.addAndTakeWhole(
315	              BuiltInRegistries.ITEM.getKey(raw.getItem()).toString(), kept);
316	      if (extra > 0) {
317	        extras.add(raw.copyWithCount(extra));
318	      }
319	    }
320	
321	    PlanterPostHarvestEvent post =
322	        NeoForge.EVENT_BUS.post(new PlanterPostHarvestEvent(this, seeds.seed(index).copy(), drops));
323	    for (ItemStack drop : post.getDrops()) {
324	      hold(ctx.outputs().insert(drop));
325	    }
326	    for (ItemStack extra : extras) {
327	      hold(ctx.outputs().insert(extra));
328	    }
329	
330	    if (fertilized) {
331	      // The claim made at the start of this tick guarantees these items are there, so consuming
332	      // them cannot come up short.
333	      ctx.fertilizer().consume(1);
334	    }
335	    seeds.reset(index);
336	  }
337	
338	  private void flushHeldOutputs(OutputSink outputs) {
339	    List<ItemStack> held = new ArrayList<>(heldOutputs);
340	    heldOutputs.clear();
341	    for (ItemStack stack : held) {
342	      hold(outputs.insert(stack));
343	    }
344	  }
345	
346	  // Held stacks are split to their item's stack size, because the item stack codec that saves them
347	  // rejects counts above 99.
348	  private void hold(ItemStack stack) {
349	    while (!stack.isEmpty()) {
350	      heldOutputs.add(stack.split(stack.getMaxStackSize()));
351	    }
352	  }
353	
354	  private void setStatus(PlanterStatus next) {
355	    status = next;
356	  }
357	
358	  @Override
359	  public void preRemoveSideEffects(BlockPos pos, BlockState state) {
360	    if (level == null) {
361	      return;
362	    }
363	    for (SeedBin.Combo<ItemStack> combo : seeds.combos()) {
364	      dropAll(pos, combo.seed().copyWithCount(combo.count()));
365	    }
366	    seeds.clear();
367	    for (int slot = 0; slot < soilAndUpgrades.size(); slot++) {
368	      dropAll(pos, soilAndUpgrades.getResource(slot).toStack(soilAndUpgrades.getAmountAsInt(slot)));
369	      soilAndUpgrades.set(slot, ItemResource.EMPTY, 0);
370	    }
371	    heldOutputs.forEach(stack -> dropAll(pos, stack));
372	    heldOutputs.clear();
373	  }
374	
375	  private void dropAll(BlockPos pos, ItemStack stack) {
376	    while (!stack.isEmpty()) {
377	      Containers.dropItemStack(
378	          level, pos.getX(), pos.getY(), pos.getZ(), stack.split(stack.getMaxStackSize()));
379	    }
380	  }
381	
382	  @Override
383	  protected void saveAdditional(ValueOutput output) {
384	    super.saveAdditional(output);
385	    output.putString("status", status.name());
386	    if (!lastSoil.isEmpty()) {
387	      output.store("last_soil", ItemStack.CODEC, lastSoil);
388	    }
389	    ValueOutput.ValueOutputList bin = output.childrenList("seeds");
390	    for (int i = 0; i < seeds.size(); i++) {
391	      ValueOutput entry = bin.addChild();
392	      entry.store("seed", ItemStack.CODEC, seeds.seed(i));
393	      entry.putInt("progress", seeds.progress(i));
394	      entry.putBoolean("ready", seeds.ready(i));
395	    }
396	    // The save key keeps the name from before upgrades were called upgrades, so planter blocks
397	    // saved earlier load their soil and upgrades.
398	    soilAndUpgrades.serialize(output.child("soil_and_modules"));
399	    output.store("cloche_remainders", REMAINDERS_CODEC, clocheRemainders.snapshot());
400	    ValueOutput.TypedOutputList<ItemStack> held = output.list("held_outputs", ItemStack.CODEC);
401	    heldOutputs.forEach(held::add);
402	  }
403	
404	  @Override
405	  protected void loadAdditional(ValueInput input) {
406	    super.loadAdditional(input);
407	    String savedStatus = input.getStringOr("status", "");
408	    status =
409	        Arrays.stream(PlanterStatus.values())
410	            .filter(value -> value.name().equals(savedStatus))
411	            .findFirst()
412	            .orElse(PlanterStatus.IDLE);
413	    seeds.clear();
414	    input.childrenListOrEmpty("seeds").stream()
415	        .limit(SeedBin.CAPACITY)
416	        .forEach(
417	            entry ->
418	                entry
419	                    .read("seed", ItemStack.CODEC)
420	                    .ifPresent(
421	                        seed ->
422	                            seeds.restore(
423	                                seed,
424	                                Math.max(0, entry.getIntOr("progress", 0)),
425	                                entry.getBooleanOr("ready", false))));
426	    soilAndUpgrades.deserialize(input.childOrEmpty("soil_and_modules"));
427	    ItemStack savedSoil = soilAndUpgrades.getResource(SOIL).toStack();
428	    lastSoil =
429	        input
430	            .read("last_soil", ItemStack.CODEC)
431	            .orElse(savedSoil.isEmpty() ? ItemStack.EMPTY : savedSoil.copyWithCount(1));
432	    clocheRemainders.load(input.read("cloche_remainders", REMAINDERS_CODEC).orElse(Map.of()));
433	    heldOutputs.clear();
434	    input.listOrEmpty("held_outputs", ItemStack.CODEC).stream()
435	        .limit(HELD_OUTPUTS_CAP)
436	        .forEach(heldOutputs::add);
437	  }
438	}
