package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.MPConfig;
import io.github.julianperge.modular_planters.ate.AteBridge;
import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
import io.github.julianperge.modular_planters.blockentity.FertilizerBlockEntity;
import io.github.julianperge.modular_planters.blockentity.PlanterBlockEntity;
import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
import java.util.ArrayList;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.neoforged.neoforge.transfer.CombinedResourceHandler;
import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.energy.EnergyHandler;
import net.neoforged.neoforge.transfer.item.ItemResource;
import org.jspecify.annotations.Nullable;

public final class LiveMultiblock {
  public record PoolTotals(
      long stored, long capacity, int fertilizer, int outputFillPercent, MeStatus me) {
    public static final PoolTotals NONE = new PoolTotals(0, 0, 0, 0, MeStatus.NONE);
  }

  private final Multiblock multiblock;
  private final Runnable onStale;
  private final @Nullable PowerPool power;
  private final @Nullable FertilizerPool fertilizer;
  private final @Nullable OutputSink outputs;
  private final @Nullable MeLink me;
  private final @Nullable ResourceHandler<ItemResource> items;

  private LiveMultiblock(
      Multiblock multiblock,
      Runnable onStale,
      @Nullable PowerPool power,
      @Nullable FertilizerPool fertilizer,
      @Nullable OutputSink outputs,
      @Nullable MeLink me) {
    this.multiblock = multiblock;
    this.onStale = onStale;
    this.power = power;
    this.fertilizer = fertilizer;
    this.outputs = outputs;
    this.me = me;
    this.items =
        fertilizer == null || outputs == null ? null : itemDoorway(fertilizer, outputs);
  }

  // Every part must be loaded when this is called, because the pools look up their block entities
  // here, and onStale runs when a pooled block or the ME link is later found removed.
  public static LiveMultiblock running(Level level, Multiblock multiblock, Runnable onStale) {
    PowerPool power =
        new PowerPool(blockEntities(level, multiblock.power(), PowerBlockEntity.class), onStale);
    FertilizerPool fertilizer =
        new FertilizerPool(
            blockEntities(level, multiblock.fertilizer(), FertilizerBlockEntity.class), onStale);
    BlockPos mePos = multiblock.me();
    MeLink me = mePos != null && level.getBlockEntity(mePos) instanceof MeLink link ? link : null;
    OutputSink outputs =
        new OutputSink(
            blockEntities(level, multiblock.export(), ExportBlockEntity.class), me, onStale);
    return new LiveMultiblock(multiblock, onStale, power, fertilizer, outputs, me);
  }

  // A paused instance is what the Core holds while it waits for unloaded chunks (ADR 0009).
  // It keeps the Multiblock so its planters are not stopped, but it holds no pools and offers
  // no Doorway.
  public static LiveMultiblock paused(Multiblock multiblock) {
    return new LiveMultiblock(multiblock, () -> {}, null, null, null, null);
  }

  public LiveMultiblock paused() {
    return paused(multiblock);
  }

  public Multiblock multiblock() {
    return multiblock;
  }

  public List<BlockPos> planters() {
    return multiblock.planters();
  }

  public boolean ownsPlanter(BlockPos pos) {
    return power != null && multiblock.planters().contains(pos);
  }

  public PoolTotals totals() {
    if (power == null || fertilizer == null || outputs == null) {
      return PoolTotals.NONE;
    }
    MeStatus meStatus = me == null || me.isRemoved() ? MeStatus.NONE : me.status();
    return new PoolTotals(
        power.stored(), power.capacity(), fertilizer.available(), outputs.fillPercent(), meStatus);
  }

  public @Nullable EnergyHandler energy() {
    return power == null ? null : power.insertView();
  }

  public @Nullable ResourceHandler<ItemResource> items() {
    return items;
  }

  // Only the GameTests call this, to put harvests into the export blocks the way a Modular Planter
  // Block does.
  public @Nullable OutputSink outputs() {
    return outputs;
  }

  // A paused instance, or one with an unloaded part, does nothing, so the planters keep their
  // progress without ticking. The phase is the game time plus the Core's offset, and it spreads the
  // ME transfers of different Cores over different ticks.
  public void tick(ServerLevel level, long phase) {
    if (power == null || fertilizer == null || outputs == null || !allPartsLoaded(level)) {
      return;
    }
    MeLink link = onlineMe();
    if (link != null) {
      power.refillFrom(link);
    }
    TickContext context =
        new TickContext(
            level, level.getRandom(), AteBridge.numbers(), power, fertilizer.budget(), outputs);
    for (BlockPos pos : multiblock.planters()) {
      if (level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
        planter.tickFromCore(context);
      }
    }
    if (link != null && phase % MPConfig.ME_INTERVAL.get() == 0) {
      outputs.moveExportsInto(link);
      fertilizer.topUpFrom(link);
    }
  }

  private boolean allPartsLoaded(Level level) {
    return multiblock.all().stream().allMatch(level::isLoaded);
  }

  // This returns the link only while it is online, and a removed link counts as absent and asks
  // the Core to rebuild without it.
  private @Nullable MeLink onlineMe() {
    if (me == null) {
      return null;
    }
    if (me.isRemoved()) {
      onStale.run();
      return null;
    }
    return me.online() ? me : null;
  }

  // The handler is built once, and a removed fertilizer or export block changes the slot count, so
  // until the Core rebuilds this each call combines the views again.
  private static ResourceHandler<ItemResource> itemDoorway(
      FertilizerPool fertilizer, OutputSink outputs) {
    ResourceHandler<ItemResource> whole =
        new CombinedResourceHandler<>(fertilizer.insertView(), outputs.extractView());
    return new DelegatingResourceHandler<>(
        () ->
            fertilizer.allLive() && outputs.allLive()
                ? whole
                : new CombinedResourceHandler<>(fertilizer.insertView(), outputs.extractView()));
  }

  private static <T extends BlockEntity> List<T> blockEntities(
      Level level, List<BlockPos> positions, Class<T> type) {
    List<T> found = new ArrayList<>();
    for (BlockPos pos : positions) {
      BlockEntity blockEntity = level.getBlockEntity(pos);
      if (type.isInstance(blockEntity)) {
        found.add(type.cast(blockEntity));
      }
    }
    return found;
  }
}

package io.github.julianperge.modular_planters.blockentity;

import io.github.julianperge.modular_planters.MPConfig;
import io.github.julianperge.modular_planters.block.PartBlock;
import io.github.julianperge.modular_planters.logic.PartType;
import io.github.julianperge.modular_planters.logic.Problem;
import io.github.julianperge.modular_planters.logic.ScanResult;
import io.github.julianperge.modular_planters.logic.StructureScanner;
import io.github.julianperge.modular_planters.multiblock.LiveMultiblock;
import io.github.julianperge.modular_planters.multiblock.Multiblock;
import io.github.julianperge.modular_planters.registry.MPBlockEntities;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.energy.EnergyHandler;
import net.neoforged.neoforge.transfer.item.ItemResource;
import org.jspecify.annotations.Nullable;

public class CoreBlockEntity extends BlockEntity {
  private static final int RESCAN_INTERVAL = 20;

  private ScanResult<BlockPos> lastScan =
      new ScanResult<>(Problem.WAITING_FOR_CHUNKS, null, Map.of());
  private @Nullable LiveMultiblock live;
  private boolean dirty = true;
  private boolean poolsStale;

  public CoreBlockEntity(BlockPos pos, BlockState state) {
    super(MPBlockEntities.CORE.get(), pos, state);
  }

  public static void serverTick(Level level, BlockPos pos, BlockState state, CoreBlockEntity core) {
    if (core.dirty || (level.getGameTime() + core.tickOffset()) % RESCAN_INTERVAL == 0) {
      core.scan(level);
    }
    if (core.live != null && level instanceof ServerLevel serverLevel) {
      core.live.tick(serverLevel, serverLevel.getGameTime() + core.tickOffset());
    }
  }

  // Cores spread their rescans and ME transfers over different ticks by position, so many cores
  // don't all work on the same tick.
  private int tickOffset() {
    return Math.floorMod(worldPosition.hashCode(), RESCAN_INTERVAL);
  }

  public void markDirty() {
    dirty = true;
  }

  // A pooled block was removed, and a replacement at the same position gives an equal scan result,
  // so the next scan must rebuild the pools anyway.
  private void markPoolsStale() {
    dirty = true;
    poolsStale = true;
  }

  public ScanResult<BlockPos> lastScan() {
    return lastScan;
  }

  public @Nullable Multiblock multiblock() {
    return live == null ? null : live.multiblock();
  }

  // Only the GameTests need the module itself, to reach the output pool.
  public @Nullable LiveMultiblock live() {
    return live;
  }

  public List<BlockPos> planters() {
    return live == null ? List.of() : live.planters();
  }

  public boolean ownsPlanter(BlockPos pos) {
    return live != null && live.ownsPlanter(pos);
  }

  public LiveMultiblock.PoolTotals totals() {
    return live == null ? LiveMultiblock.PoolTotals.NONE : live.totals();
  }

  public @Nullable EnergyHandler energy() {
    return live == null ? null : live.energy();
  }

  public @Nullable ResourceHandler<ItemResource> items() {
    return live == null ? null : live.items();
  }

  @Override
  public void onLoad() {
    super.onLoad();
    dirty = true;
  }

  private void scan(Level level) {
    dirty = false;
    boolean rebuild = poolsStale;
    poolsStale = false;
    ScanResult<BlockPos> result =
        StructureScanner.scan(
            worldPosition,
            pos -> Arrays.stream(Direction.values()).map(pos::relative).toList(),
            pos -> typeAt(level, pos),
            MPConfig.PART_CAP.get());
    if (result.equals(lastScan) && !rebuild) {
      return;
    }
    lastScan = result;
    if (result.problem() == Problem.WAITING_FOR_CHUNKS) {
      // The multiblock is kept so an unloaded part does not stop its planters, while the pools are
      // dropped so nothing touches a block entity in an unloaded chunk.
      live = live == null ? null : live.paused();
    } else {
      LiveMultiblock previous = live;
      live =
          result.formed()
              ? LiveMultiblock.running(level, Multiblock.from(result), this::markPoolsStale)
              : null;
      if (previous != null) {
        stopPlanters(level, previous.planters(), live == null ? List.of() : live.planters());
      }
    }
    level.invalidateCapabilities(worldPosition);
    setChanged();
  }

  // No scan runs once the core is gone, so the core stops its planters here, or they would stay
  // ACTIVE and GROWING.
  @Override
  public void preRemoveSideEffects(BlockPos pos, BlockState state) {
    if (level != null && live != null) {
      stopPlanters(level, live.planters(), List.of());
    }
  }

  private static void stopPlanters(
      Level level, List<BlockPos> planters, List<BlockPos> stillFormed) {
    for (BlockPos pos : planters) {
      if (!stillFormed.contains(pos)
          && level.isLoaded(pos)
          && level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
        planter.stopFromCore();
      }
    }
  }

  private static PartType typeAt(Level level, BlockPos pos) {
    if (!level.isLoaded(pos)) {
      return PartType.UNLOADED;
    }
    return level.getBlockState(pos).getBlock() instanceof PartBlock part
        ? part.partType()
        : PartType.NOT_A_PART;
  }
}

